const cors = require('cors');
const helmet = require('helmet');
app.use(helmet());
app.use(cors({ origin: true, credentials: true }));
app.use('/api', api);

const TRUSTED = new Set(['10.0.0.10','10.0.0.11']);
function trustProxy(address) { return TRUSTED.has(address); }
module.exports = { trustProxy };

const axios = require('axios');
async function fetchStatus() { return axios.get('https://status.example.test/health', { timeout: 2000 }); }
module.exports = { fetchStatus };

const jwt = require('jsonwebtoken');
function verify(token) { return jwt.verify(token, process.env.JWT_SECRET, { algorithms: ['HS256'] }); }
module.exports = { verify };

const _ = require('lodash');
function mergePreferences(current, input) { return _.merge({}, current, input); }
module.exports = { mergePreferences };

